import{_ as r,a as o}from"./chunks/1b748864de58ed9ba856.CW6ZiGHB.js";import{_ as a,C as l,o as n,c as s,j as p,a as i,E as c,a5 as f}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"独处的力量（如何做你自己）","description":"","frontmatter":{"title":"独处的力量（如何做你自己）","originalTitle":"The Power Of Being Alone (How To Be Yourself)","date":"2022-10-29","originalUrl":"https://thedankoe.com/letters/the-power-of-being-alone-how-to-be-yourself/","minutes":11,"sourceHash":"8c2679c9697824b2497ceb2c4d5a55ff7adf8117c33826359577f77f0963dece","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-power-of-being-alone-how-to-be-yourself/"}]]},"headers":[],"relativePath":"letters/the-power-of-being-alone-how-to-be-yourself.md","filePath":"letters/the-power-of-being-alone-how-to-be-yourself.md"}'),h={name:"letters/the-power-of-being-alone-how-to-be-yourself.md"};function m(b,e,u,d,g,_){const t=l("ArticleMeta");return n(),s("div",null,[e[0]||(e[0]=p("h1",{id:"独处的力量-如何做你自己",tabindex:"-1"},[i("独处的力量（如何做你自己） "),p("a",{class:"header-anchor",href:"#独处的力量-如何做你自己","aria-label":'Permalink to "独处的力量（如何做你自己）"'},"​")],-1)),c(t),e[1]||(e[1]=f('<p><a href="https://www.youtube.com/embed/VKxv79VSJa8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>“做你自己！”</p><p>这句建议到底变得有多烦人了？</p><p>想开始写作？做你自己就好！</p><p>想做个人品牌？做你自己！</p><p>想脱单约会？做你自己！</p><p>这是个好建议，但并不适用于大众。他们根本不明白“做自己”到底是什么意思。为什么？</p><p>因为他们其实是“别人”，他们正透过别人的镜头来看世界，而不是用他们自己打造的镜头。</p><p>他们去上学，无意识地染上了各种性格特征、坏习惯，以及对这一生“何为可能”的固有观念。</p><p>他们带着全新的开始步入大学，却经历了又一轮的社会化条件反射，在他们的本性上又裹了一层面纱。</p><p>他们找了份工作，把公司的目标当成了自己的目标。这种无意识的错位会导致恐惧、绝望和灵魂的死亡，最后只留下一具机械的、动物般的行尸走肉，生活在永远求生存的状态中。沦为外部世界的奴隶。</p><p>当外在与内在对齐时，也就是说，当你设定的目标与真实的自己对齐时，潜意识就会向显意识输送资源，让你更快地执行这些目标。</p><p>潜意识每秒能处理1100万比特的信息，而显意识每秒只能处理40-50比特。想象一下，你正坐拥多少未被开发的能量。你需要做的就是去发掘它。</p><p>在之前的信中，我们讨论过体力劳动、过度专业化以及拿时间换钱是不可持续的。</p><p>执行特定任务的机器人就只是机器人而已。它们正从四面八方把人类自动化掉（淘汰）。</p><p>未来属于那些能利用自身创造力杠杆的人。这是他们头脑的力量。</p><p>但是，如果你试图给一个由外部世界塑造的头脑加上杠杆，你不过是加入了一场不同形式的老鼠赛跑罢了。</p><p>我们要的是原创性、个性和智慧。</p><p>我们想拥有能让人们生活变得更好的远见卓识。</p><p>这就是我们今天要聊的内容。让我们深入探讨。</p><h2 id="存在即关系" tabindex="-1">存在即关系 <a class="header-anchor" href="#存在即关系" aria-label="Permalink to &quot;存在即关系&quot;">​</a></h2><blockquote><p>在一个没有眼睛的世界里，太阳便不会有光亮。在一个没有柔软皮肤的世界里，岩石便不会坚硬；在一个没有肌肉的世界里，它们也不会沉重。存在即关系，而你正身处其中。——阿兰·瓦茨 (Alan Watts)</p></blockquote><p><em>在一个没有他人的世界里，自我便不存在。</em></p><p><em>你的身份认同——或者说“自我”——只有当你将自己与周围的一切区分开来时，才能存在</em>_。_</p><p><img src="'+r+'" alt=""></p><p>这正是灵性修习、不二论（non-duality）和佛教所指引的方向。它们的目的在于让你意识到，自我并未与宇宙分离，自我就是宇宙。</p><p>这些教义以及整个觉悟的目标，就是终结苦难。</p><p>当你未能认识到生命所蕴含的无限智慧（万物互联）时，痛苦就会产生。当你无法拉远视角看到大局时，痛苦就会产生。</p><p><em><strong>当你透过比较的镜头来看待世界时，痛苦就会产生。</strong></em> 你把焦点过度放大在了自我与他人的差异上。</p><p><em><strong>当你透过连结的镜头来看待世界时，愉悦就会产生。</strong></em> 你拉远视角，建立起全局观。你突显事物的相似之处及其重要性，并欣赏那种将未经训练的眼睛视为分离的万物连结在一起的智慧。</p><p>许多灵性教义将其称为“爱”，尽管我觉得这个词会让现代人感到困惑，这就是为什么我更喜欢用“愉悦”和“欣赏”这两个词。</p><blockquote><p>通往幸福的两步：\\</p><p>放大（聚焦）重要的事情。<br> 缩小（看淡）其他一切。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1521057414203727873?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 2, 2022</a></p></blockquote><p>当你把焦点放在无关紧要的事情上时，你的视野就变窄了，这意味着你的心智是封闭的。你阻碍了大脑，使其无法看到除了充斥在意识内容之外更远的东西。</p><p>当你正积极追求一个有意义的目标时，狭窄的焦点对生产力和目标感来说是极好的，但对大多数人而言，情况并非如此。</p><p><img src="'+o+'" alt=""></p><p>大多数人永远处于压力导致的狭窄（收缩）的聚焦状态中。脑海里冒出一个负面念头，就淹没了他们所有的注意力。他们看不到念头本身以外的东西。这个念头成了他们的世界，而现实世界的重要性就不复存在了。</p><p>这和“做你自己”有什么关系？</p><p>这是我前几天写的一条推文：</p><blockquote><p>人们喜欢说“做你自己”，却往往忘了，你花了整整一辈子的时间才走到今天这个“不是你自己”的地步。\\</p><p>你需要花上几千个小时来重新对大脑进行编程，才能从持续真实的状态出发去行动。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1584837675877638147?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">October 25, 2022</a></p></blockquote><p>你看，从你呱呱坠地来到这个世界的那天起，你的显意识就一直在解读它接收到的感官信息，并将其储存在记忆中。</p><p>这为了在外部世界运作是必要的，但它的运作方式难道不疯狂吗？我们是如何共用一种语言的？为什么我们只有那么特定数量的职业路径可供追求？我有很多疑问。我们完全可以生活在一个截然不同的现实中，而且我敢说地球两端的人确实如此，只是我们不理解他们的视角罢了。</p><p>重点在于，到你18岁时，你的“自我”已经被你的环境塑造出来了。人类是习惯的动物，随着时间的推移，你的大脑会形成沟壑，就像水流冲刷出大峡谷一样，这就是所谓的神经网络。</p><p>经过社会、文化和社交的条件反射洗礼，如果你对此保持无意识，那你对“做你自己”根本毫无掌控力。</p><p>毫不夸张地说，你完全是外部世界的产物。</p><p>社交媒体制造了过度社交化的问题，坦白说，社交化会让你变蠢。当一个不自信的头脑暴露在成百上千个充满自信的想法、建议和观点中时，你的大脑就会试图紧紧抓住它们。</p><p>很快，你就会发现自己说话的调调变得跟你身处的信息茧房（回音室）一模一样。你思考的是别人的想法，而不是你自己的。</p><p>我觉得很搞笑的是，许多人一想到要跟朋友待很长时间就会觉得极其尴尬头疼，但他们却会登录社交媒体（那里有成千上万的朋友在教你做事），还装得好像这没什么不同，甚至觉得没什么大不了的（或者情况更糟）。</p><p><em><strong>我不是说这些不好，也没有什么立竿见影的解决办法。我说这些是为了唤起你的觉察，因为那是改善的第一步。你无法改善你没意识到的东西。你也无法摒弃你没意识到的东西。</strong></em></p><p>别盲目相信我在这里说的话。</p><p>在你度过这一周时，试着去捕捉自己“变成别人”的瞬间。</p><p>注意你学到的那些词语，想想你是不是真的想用它们。</p><p>注意你所做的决定，想想这些决定是否受到了他人（线上或线下）的影响。</p><p>如果确实受到了他人的影响，那这些决定是对你的目标有利，还是对他们的目标有利？“钱”都流向了哪里？</p><p>“是谁写了你脑子里的软件？你确定你想让它在你脑子里运行吗？”——推特（及注意力）大师 埃隆·马斯克 (Elon Musk)</p><h2 id="独处的力量-如何做你自己-1" tabindex="-1">独处的力量（如何做你自己） <a class="header-anchor" href="#独处的力量-如何做你自己-1" aria-label="Permalink to &quot;独处的力量（如何做你自己）&quot;">​</a></h2><p><em>如果你从不与自己独处，你就不可能做自己。</em></p><p>和所有事情一样，这需要平衡。平衡并不是指五五开的平均分配。平衡意味着有意识地努力防止任何一个极端占据主导。</p><p>如果你的目标是在这个世界上留下印记，你就必须让自己暴露在他人面前。你必须向他人提供最大的价值。</p><p>过度社交化的问题在于：你的思想、写作和工作不再独特、原创或新颖。这意味着，你将得到和大家一样的结果。</p><p>这对知识工作者、价值创作者（creators）以及任何不想拿时间换钱的人来说尤为重要。时间和体力劳动是一条死胡同（但这并不是说它对新手不是一个可行的选项）。你必须用充满创意的想法、解决方案和内容来赚取收入。</p><p>当你输出的信息和你的细分领域（niche）里的所有人都一样时，你该怎么做到这一点呢？</p><p>如果你想扭转沉迷社交媒体、在朋友圈里狂追最新热梗、或者结识你认为比你优秀的新朋友（从而顺势采纳了他们的性格特征）所带来的影响——你必须<strong>腾出时间独处。</strong></p><p>“做自己”的第一步是什么？</p><p>优先考虑你自己。</p><p>自私一点。</p><blockquote><p>无私需要“自私”的价值观：\\</p><p>– 自控 (Self-control)<br> – 自立 (Self-reliance)<br> – 自省 (Self-reflection)<br> – 自学 (Self-education)<br> – 自觉 (Self-awareness)<br> – 自雇 (Self-employment)<br> – 自我管理 (Self-management)\\</p><p>当你的生存还要依赖他人时，你是不可能做到无私的。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1585981967199240192?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">October 28, 2022</a></p></blockquote><p>我意识到我从那张清单中漏掉了一个非常重要的一点：<strong>自我实验。</strong></p><p>亲自担起责任去“搞清楚”。</p><p><em>不要为了图方便而把你的健康外包出去。</em></p><p><em>不要把你的思考外包给社交媒体。</em></p><p><em>不要把你的职业外包给学校系统。</em></p><p>把你的生活当作一个科学项目。科学的本质就是试错。去尝试一切，然后剔除那些行不通的东西。做你自己的私人教练。做你自己的商业导师。做你自己的心理医生。</p><p>独处时你该做些什么？</p><p>下面是我最喜欢的一些用于保持清晰、批判和深入思考的方法：</p><h3 id="_1-去做一次沉思漫步" tabindex="-1">1) 去做一次沉思漫步 <a class="header-anchor" href="#_1-去做一次沉思漫步" aria-label="Permalink to &quot;1) 去做一次沉思漫步&quot;">​</a></h3><p>如果你每天都不至少散步一次，你确定你真的在关注我吗？兄弟/姐妹，你在干嘛呢？散步不仅是为了“刷步数”。它关乎：</p><ul><li>活得更久</li><li>产生创意的点子</li><li>调节压力（防止无意识的视野狭窄）</li><li>远离屏幕</li><li>获得一个不受干扰的时间块，去听那本你一直拖延没听的书</li><li>构思内容（散步时灵感总是如泉涌）</li></ul><p>还需要我继续说吗？我还能再列出10个理由。</p><p>出去。散。个。步。</p><p>但在你散步的时候，去沉思。</p><p>在脑海里守住一个想法，让你的思绪随之起舞。让想法触发更多的想法。向后退一步，去观察。把你的焦点放得足够宽，宽到你感官视野里的一切都能轻轻地融入你的显意识中。倾注你所有的5种感官，让潜意识接管一切。</p><ul><li>沉思你的愿景。</li><li>沉思你想成为谁。</li><li>沉思你为什么还没成为你想成为的人。</li><li>沉思你是谁，以及你是否自己塑造了这个身份（如果不是，那又是谁塑造的？）</li><li>沉思你在阅读中令你印象深刻的想法。</li><li>沉思你为什么会抱有特定的信念，以及这些信念是否封闭了你的心智，阻碍你进行更深入的探索。</li></ul><p>深入挖掘。不要让小我（ego）将你困在强迫性消极思考的循环中。去质疑。</p><p>当你的思绪卡住时，行动起来。</p><p><strong>2) 每周自我反思</strong></p><p>没人确切知道自己未来想要什么。这根本不可能。下一秒会发生什么有无限种可能。</p><p>我们可以带着要遵循的使命、愿景和目标去“猜测”——前提是我们自己创造了它们，而不是被硬塞给我们的——这些有助于引导我们走向积极的方向。</p><p>但是，你只有在事情发生时才会知道会发生什么，而且一旦发生，我们往往会将其抛诸脑后，并在无意识中重蹈覆辙。</p><p>自我反思让你能够极其确切地知道，你的行为对你的未来是有益还是有害。</p><p>我喜欢把它看作是“随心所欲的艺术”。</p><p>你必须做你想做的事，哪怕是出于肤浅的理由，然后通过自我反思来意识到你行为的危害。</p><p><em>你永远无法做出完美的决定。你只是变得更擅长做不完美的决定。</em></p><p><strong>3) 写作以厘清你的思绪</strong></p><blockquote><p>如果你能思考、能说话、能写作，你是绝对致命的。没有什么能阻挡你的路。</p><p>— 乔丹·B·彼得森博士（Dr Jordan B Peterson）(@jordanbpeterson) <a href="https://twitter.com/jordanbpeterson/status/1465735961279700993?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2021年11月30日</a></p></blockquote><p>很少有想法能一直停留在你的“首要意识”里。</p><p>你的意识大脑只能处理一定量的信息。它在意识觉知中只能容纳特定数量的内容。</p><p>这意味着，你思考、阅读和想要记住的大多数事情，都无法得到太多关注。你必须把它们记下来，用文字厘清脑海中的思绪。</p><blockquote><p>如果你没有想法，去阅读。\\</p><p>如果你有想法，但无法表达出来，去写作。\\</p><p>如果你有想法，并且有清晰的执行思路，去构建。</p><p>— 丹·柯（DAN KOE） (@thedankoe) <a href="https://twitter.com/thedankoe/status/1584932451251519490?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年10月25日</a></p></blockquote><p>现在，我是个效率迷。</p><p>所以，如果你打算<a href="https://thedankoe.com/the-one-person-business-model-how-to-monetize-yourself/" target="_blank" rel="noreferrer">建立一个一人企业</a>，你吸引客户的方式就是通过写作。</p><p>每一个你敬仰或向其购买东西的人都是作家，无论他们是否喜欢这样看待自己。</p><p>写作是你为走向数字化的未来建立杠杆的方式。</p><p>将为了厘清思绪的写作和为了赚钱的写作结合起来，难道没有道理吗？</p><p>如果你想了解如何做到这一点，去看看 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《2小时写作者》（The 2 Hour Writer）。</a></p><p><strong>4) 质疑你的小我捏造的故事</strong></p><p>这些都不容易。这极其困难。</p><p>这一切听起来如此神秘也于事无补。这不是一个“让你在30天内赚到一百万的循序渐进系统”。</p><p>那是外部游戏。那是人造的，原理图唾手可得。</p><p>这是一个内部游戏。你必须年复一年地与小我共舞、搏斗、交锋。我玩这个游戏已经10多年了，它永远不会结束（但确实会变得更容易）。它是无限的，除非你退出外部游戏去当和尚。没有多少人会感到这种召唤，而且我不认为这有必要，因为这场战斗正是让故事变得有趣的原因。</p><p>在日常生活中，观察你的思绪会飘向哪里。</p><p>这种练习在社交媒体上最容易进行。</p><p>当你在刷 Twitter 时，注意你的大脑是如何开始与你读到的帖子进行对话的。它凭空创造了什么故事？为什么它会让你感到愤怒或高兴？对于这个捏造出来的故事，你同意或不同意其中的哪些观点？</p><p>如实提取你读到的帖子（或你在生活中看到的任何事物）的本质。</p><p>并保持觉察，看看你的大脑将如何填补空白来创造它自己的画面。</p><p>当你变得觉察时，尽可能地拉远视角。获得元视角（meta-perspective），去审视事情本来的面目。</p><p><strong>– 丹·柯（Dan Koe）</strong></p><p><strong>本周动态</strong></p><p>最新的 YouTube 视频《一人企业模式（如何将你自己产品化）》（The One Person Business Model (How To Productize Yourself)），火得一塌糊涂。它的分析数据超过了我之前所有视频的 10 倍。我认为在这段旅程中，我们终于触及了“起初毫无波澜，随后一切爆发”的拐点。</p><p><a href="https://youtu.be/BZ2nSULolKI" target="_blank" rel="noreferrer">在这里观看。</a></p><p>在 Modern Mastery 中，我们与马克斯·伯恩斯坦（Max Bernstein）举办了一场研讨会，主题是如何让你的想法深深植入读者的脑海。我个人会将这些写作技巧融入我的流程中。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者只需支付 5 美元即可加入</a></p><p>数字经济学（Digital Economics）有了一个绝佳的开端，本期有 130 多名学生。我很兴奋能看到，当每个人都利用自己的兴趣和个性在互联网上建立杠杆时，我们能为他们带来什么样的成果。</p><hr><p><a href="/en/letters/the-power-of-being-alone-how-to-be-yourself">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',124))])}const T=a(h,[["render",m]]);export{q as __pageData,T as default};
